SELECT EXISTS(
  SELECT 1 FROM "ecommerce"."Order"
  WHERE "chatbotId" = '{{ $('When Called by Platform').item.json.chatbotId }}'
    AND "sessionId" = '{{ $('When Called by Platform').item.json.sessionId }}'
    AND "createdAt" > NOW() - INTERVAL '2 minutes'
) AS "isOrderCreated";

UPDATE "chatbot"."ChatSession" SET "lastMessage" = '{{ $('Format Response').item.json.replyText.replace(/'/g, "''").slice(0, 500) }}', "updatedAt" = NOW() WHERE "chatbotId" = '{{ $('When Called by Platform').item.json.chatbotId }}' AND "sessionId" = '{{ $('When Called by Platform').item.json.sessionId }}';

